				\begin{document}$$ S_{original} \mathop{\longrightarrow}\limits^{augment}S_{new} \left[ {\overbrace {{s_{1},s_{2}, \ldots,X}}^{i - 1},\;\overbrace {{s_{i + 1}, \ldots,s_{32} }}^{32 - i}} \right] $$\end{document}

